import React from "react";
import {
  FaArrowRight,
  FaTag,
  FaUserCircle,
  FaUser,
  FaPhone,
  FaMobileAlt,
  FaMapMarkerAlt,
  FaMapMarkedAlt,
  FaMicrochip,
  FaShieldAlt,
  FaQuestionCircle,
  FaClock,
  FaLink,
  FaFileAlt,
  FaMoneyBillWave,
  FaTools,
  FaPercentage,
  FaExclamationCircle,
  FaPlus,
  FaComments,
  FaReceipt,
} from "react-icons/fa";

class RequestDetails extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      request: {
        requestNumber: "1405050027",
        technicianName: "علی عبداللهی",
        customerName: "مخاخری",
        mobile: "09121457004",
        landline: "---",
        province: "تهران",
        address: "شهریار بعدیل بادامک یاسک ۶ امورز",
        deviceType: "ساید",
        brand: "سامسونگ_SAMSUNG",
        deviceProblem: "یخچال گرم و لاستیک",
        visitDate: "1405/05/28",
        description: "",
        status: "تسویه شده",

        totalReceived: "۲۸,۰۰۰,۰۰۰ تومان",
        consumableCost: "۴,۰۰۰,۰۰۰ تومان",
        consumables:
          "لاستیک درب، فیلترها، ترموویزر، سنسور",
        totalWage: "۲۴,۰۰۰,۰۰۰ تومان",
        commission: "۱۲,۰۰۰,۰۰۰ تومان",

        receiptImage:
          "https://via.placeholder.com/300x220?text=Payment+Receipt",

        settlementDescription: "تایید است",

        relatedRequests: [],
      },
    };
  }

  componentDidMount() {
    /*
      بعداً API را اینجا وصل کن.

      مثال:

      const requestId = this.props.match?.params?.id;

      fetch(`/api/requests/${requestId}`)
        .then((response) => response.json())
        .then((data) => {
          this.setState({
            request: data
          });
        });
    */
  }

  handleBack = () => {
    window.history.back();
  };

  handleAddRelatedRequest = () => {
    /*
      بعداً API افزودن درخواست مرتبط اینجا قرار می‌گیرد.
    */
  };

  renderInfo = (icon, title, value, extraClass = "") => {
    const Icon = icon;

    return (
      <div className="request-detail-box">
        <div className="request-detail-icon">
          <Icon />
        </div>

        <div className="request-detail-text">
          <span className="request-detail-title">
            {title}:
          </span>

          <span className={`request-detail-value ${extraClass}`}>
            {value || ""}
          </span>
        </div>
      </div>
    );
  };

  render() {
    const { request } = this.state;

    return (
      <div className="request-details-page container">

        <style>
          {`
            .request-top-bar {
              height: 58px;
              display: flex;
              align-items: center;
              justify-content: space-between;
              margin-bottom: 10px;
            }

            .request-top-icon {
              color: #ee817c;
              font-size: 25px;
            }

            .request-back-btn {
              width: 42px;
              height: 42px;
              border-radius: 50%;
              border: 1px solid #777;
              background: #fff;
              color: #777;
              display: flex;
              align-items: center;
              justify-content: center;
              font-size: 19px;
              transition: all .25s ease;
            }

            .request-back-btn:hover {
              background: #f5f5f5;
              transform: translateX(2px);
            }

            .request-detail-box {
              width: 100%;
              min-height: 75px;
              border: 1px solid #cfcfcf;
              border-radius: 12px;
              margin-bottom: 10px;
              padding: 12px 14px;

              display: flex;
              align-items: center;
              gap: 13px;

              background: #fff;

              transition:
                box-shadow .25s ease,
                transform .25s ease,
                border-color .25s ease;
            }

            .request-detail-box:hover {
              border-color: #b8b8b8;
              box-shadow: 0 3px 12px rgba(0, 0, 0, .04);
            }

            .request-detail-icon {
              width: 32px;
              min-width: 32px;

              display: flex;
              align-items: center;
              justify-content: center;

              color: #2d288e;
              font-size: 22px;
            }

            .request-detail-text {
              flex: 1;

              display: flex;
              align-items: center;
              flex-wrap: wrap;
              gap: 8px;

              font-size: 15px;
              line-height: 1.8;
            }

            .request-detail-title {
              font-weight: 700;
              color: #171717;
              white-space: nowrap;
            }

            .request-detail-value {
              color: #222;
              font-weight: 400;
            }

            .request-status {
              color: #55a9c0;
            }

            .request-receipt-box {
              min-height: 225px;
              align-items: flex-start;
            }

            .request-receipt-content {
              flex: 1;
              display: flex;
              flex-direction: column;
              gap: 10px;
            }

            .request-receipt-title {
              font-weight: 700;
              font-size: 15px;
            }

            .request-receipt-image {
              width: 255px;
              max-width: 100%;
              height: 190px;
              object-fit: contain;
              border-radius: 10px;
              background: #f4f4f4;
              border: 1px solid #eee;
            }

            .related-section {
              margin-top: 75px;
            }

            .related-title {
              font-size: 16px;
              font-weight: 700;
              margin-bottom: 18px;
            }

            .related-empty {
              text-align: center;
              color: #aaa;
              font-size: 14px;
              margin-bottom: 38px;
            }

            .related-empty-icon {
              font-size: 25px;
              margin-bottom: 8px;
              color: #aaa;
            }

            .related-add-btn {
              width: 100%;
              height: 54px;

              border: none;
              border-radius: 16px;

              background: #4d83ed;
              color: #fff;

              font-size: 15px;

              box-shadow:
                0 4px 8px rgba(77, 131, 237, .25);

              transition:
                transform .2s ease,
                box-shadow .2s ease,
                background .2s ease;
            }

            .related-add-btn:hover {
              background: #4075df;
              transform: translateY(-1px);
              box-shadow:
                0 6px 14px rgba(77, 131, 237, .28);
            }

            .related-add-btn:active {
              transform: translateY(1px);
            }

            @media (max-width: 576px) {
              .request-details-page {
                padding: 5px 10px 100px;
              }

              .request-detail-box {
                min-height: 73px;
                padding: 11px 12px;
                border-radius: 12px;
              }

              .request-detail-text {
                font-size: 14px;
                gap: 6px;
              }

              .request-detail-icon {
                width: 30px;
                min-width: 30px;
                font-size: 21px;
              }

              .request-receipt-box {
                min-height: 225px;
              }

              .request-receipt-image {
                width: 250px;
                height: 185px;
              }

              .related-section {
                margin-top: 70px;
              }
            }
          `}
        </style>

        {/* Header */}
        <div className="request-top-bar">

          <div className="request-top-icon">
            <FaComments />
          </div>

          <button
            type="button"
            className="request-back-btn"
            onClick={this.handleBack}
          >
            <FaArrowRight />
          </button>

        </div>

        {/* اطلاعات درخواست */}

        {this.renderInfo(
          FaTag,
          "شماره درخواست",
          request.requestNumber
        )}

        {this.renderInfo(
          FaUserCircle,
          "نام تعمیرکار",
          request.technicianName
        )}

        {this.renderInfo(
          FaUser,
          "نام مشتری",
          request.customerName
        )}

        {this.renderInfo(
          FaPhone,
          "شماره تماس",
          request.mobile
        )}

        {this.renderInfo(
          FaMobileAlt,
          "تلفن ثابت",
          request.landline
        )}

        {this.renderInfo(
          FaMapMarkerAlt,
          "استان",
          request.province
        )}

        {this.renderInfo(
          FaMapMarkedAlt,
          "آدرس",
          request.address
        )}

        {this.renderInfo(
          FaMicrochip,
          "نوع دستگاه",
          request.deviceType
        )}

        {this.renderInfo(
          FaShieldAlt,
          "برند دستگاه",
          request.brand
        )}

        {this.renderInfo(
          FaQuestionCircle,
          "ایراد دستگاه",
          request.deviceProblem
        )}

        {this.renderInfo(
          FaClock,
          "زمان مراجعه",
          request.visitDate
        )}

        {this.renderInfo(
          FaLink,
          "توضیحات",
          request.description
        )}

        {this.renderInfo(
          FaFileAlt,
          "وضعیت",
          request.status,
          "request-status"
        )}

        {/* مالی */}

        {this.renderInfo(
          FaMoneyBillWave,
          "کل دریافتی",
          request.totalReceived
        )}

        {this.renderInfo(
          FaMoneyBillWave,
          "هزینه لوازم مصرفی",
          request.consumableCost
        )}

        {this.renderInfo(
          FaTools,
          "لوازم مصرفی",
          request.consumables
        )}

        {this.renderInfo(
          FaPercentage,
          "کل اجرت",
          request.totalWage
        )}

        {this.renderInfo(
          FaPercentage,
          "پورسانت (50%)",
          request.commission
        )}

        {/* فیش واریزی */}

        <div className="request-detail-box request-receipt-box">

          <div className="request-detail-icon">
            <FaReceipt />
          </div>

          <div className="request-receipt-content">

            <div className="request-receipt-title row">
              <div class></div>
              <div class></div>

              فیش واریزی:
              <img
                src={request.receiptImage}
                alt="فیش واریزی"
                className="request-receipt-image me-4"
              />
            </div>
          </div>

        </div>

        {/* توضیحات تایید تسویه */}

        {this.renderInfo(
          FaExclamationCircle,
          "توضیحات تایید تسویه",
          request.settlementDescription
        )}

        {/* درخواست های مرتبط */}

        <div className="related-section">

          <div className="related-title text-center">
            درخواست های مرتبط:
          </div>

          {request.relatedRequests.length === 0 ? (
            <div className="related-empty">

              <div className="related-empty-icon">
                <FaLink />
              </div>

              <div>
                هنوز موردی برای نمایش وجود ندارد.
              </div>

            </div>
          ) : (
            request.relatedRequests.map((item) => (
              <div
                key={item.id}
                className="request-detail-box"
              >
                {item.title}
              </div>
            ))
          )}

          <button
            type="button"
            className="related-add-btn"
            onClick={this.handleAddRelatedRequest}
          >
            <FaPlus className="ms-2" />
            افزودن درخواست مرتبط
          </button>

        </div>

      </div>
    );
  }
}

export default RequestDetails;
